<?php declare(strict_types=1);require __DIR__.'/lib.php';require_once __DIR__.'/lib/user_preferences.php';lab_auth_require_admin();require_once __DIR__.'/lib/loudness.php';header('Cache-Control: no-store');$sfTheme=lab_user_theme((string)(lab_auth_current_account()['id']??''));$embed=!empty($_GET['embed'])||!empty($_POST['embed']);$message='';$error='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
 lab_require_same_origin_post();
 try{
  $action=$_POST['action']??'analyze';
  if($action==='save_timeout'){
   $current=lab_load_config();$mode=$_POST['loudness_timeout_mode']??'auto';
   if(!is_string($mode)||!in_array($mode,['auto','fixed'],true))throw new RuntimeException('Elige un modo de time-out válido.');
   $minutes=filter_var($_POST['loudness_timeout_minutes']??($current['loudness_timeout_minutes']??30),FILTER_VALIDATE_INT,['options'=>['min_range'=>3,'max_range'=>120]]);
   if($minutes===false)throw new RuntimeException('El time-out fijo debe estar entre 3 y 120 minutos.');
   $current['loudness_timeout_mode']=$mode;$current['loudness_timeout_minutes']=$minutes;lab_save_config($current);
   $message='Time-out guardado. Se aplicará a los próximos análisis; no modifica el límite de los que ya estén en ejecución.';
  }elseif($action==='analyze'){
   $n=sf_loudness_enqueue_pending((string)lab_auth_current_account()['id']);$message=$n.' análisis añadidos a la cola. Puedes cerrar el panel; se procesarán en el servidor.';
  }else throw new RuntimeException('Acción no válida.');
 }catch(Throwable $e){$error=$e->getMessage();}
}
$timeoutCfg=lab_load_config();$timeoutMode=($timeoutCfg['loudness_timeout_mode']??'auto')==='fixed'?'fixed':'auto';$timeoutMinutes=max(3,min(120,(int)($timeoutCfg['loudness_timeout_minutes']??30)));
require_once __DIR__.'/lib/processing_queue.php';require_once __DIR__.'/lib/loudness_progress.php';$progress=null;try{$db=sfq_db();sflp_capture($db,(string)lab_auth_current_account()['id']);$progress=sflp_status($db,(string)lab_auth_current_account()['id']);}catch(Throwable $e){$error='No se pudo recuperar el progreso. Puedes volver a consultarlo.';}$audit=sf_loudness_audit();?><!doctype html><html lang="es" data-theme="<?=lab_h($sfTheme)?>" data-theme-source="server"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sonoridad · Sparrow-Fy</title><link rel="stylesheet" href="assets/lab.css?v=theme-sweep1"><style>main{max-width:900px;margin:auto;padding:20px}header{display:flex;justify-content:space-between;align-items:center;gap:15px}.stats{display:flex;gap:20px;flex-wrap:wrap}.stats strong{font-size:1.4rem;display:block}</style><link rel="stylesheet" href="assets/loudness-progress.css?v=timeout-row1"><script src="assets/loudness-progress.js?v=timeout1" defer></script><meta name="sf-session-account" content="<?= htmlspecialchars((string)(lab_auth_current_account()['id']??''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') ?>"><script src="assets/session-sync.js?v=auth-poll3" defer></script>
<meta name="sf-save-result" content="<?= $error!==''?'error':(str_starts_with($message,'Time-out guardado.')?'success':'') ?>"><link rel="stylesheet" href="assets/save-feedback.css?v=2"><script src="assets/save-feedback.js?v=2"></script><script defer src=assets/sf-language.js></script></head><body><main><header><div class="sf-sonority-heading"><h1>Mantenimiento de sonoridad</h1><details class="sf-sonority-help"><summary aria-label="¿Qué hace el mantenimiento de sonoridad?" title="Analiza qué tan fuerte se percibe cada canción y guarda la medición para Normalizar. Revisa pistas sin analizar o cuyo audio cambió por un reemplazo o recorte. Trabaja en segundo plano, respetando la cola y los límites del servidor. No modifica ni recomprime el audio: al activar Normalizar, el reproductor ajusta el volumen entre canciones y conserva la dinámica dentro de cada melodía."><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/></svg></summary><div class="sf-sonority-help-content" role="note"><strong>¿Para qué sirve?</strong><p>Analiza qué tan fuerte se percibe cada canción y guarda la medición para la opción <strong>Normalizar</strong>.</p><p>Identifica pistas sin analizar o cuyo audio cambió por un reemplazo o recorte. Las procesa en segundo plano, respetando la cola y los límites del servidor.</p><p><strong>No modifica ni recomprime el audio.</strong> Al activar Normalizar, el reproductor usa esas mediciones para ajustar el volumen entre canciones, conservando la dinámica dentro de cada melodía.</p></div></details></div><a class="btn" href="config.php<?=$embed?'?embed=1':''?>">Volver atrás</a></header><?php if($message):?><p role="status"><?=lab_h($message)?></p><?php endif;if($error):?><p role="alert"><?=lab_h($error)?></p><?php endif;?><section class="card" id="loudnessTimeout"><div class="sf-timeout-heading"><h2>time-out</h2><details class="sf-sonority-help"><summary aria-label="Ayuda sobre time-out" title="Tiempo máximo para analizar una pista. Automático calcula de 3 a 30 minutos según su duración. Fijo permite elegir de 3 a 120 minutos. Al alcanzarlo se detiene solo ese análisis, no se modifica el audio ni se detiene su reproducción.">?<span class="sr-only">Ayuda</span></summary><div class="sf-sonority-help-content" role="note"><strong>Tiempo máximo de análisis por pista</strong><p>Automático adapta el límite a la duración del audio: mínimo 3 y máximo 30 minutos. Fijo utiliza el número de minutos que elijas, entre 3 y 120.</p><p>Si se alcanza el time-out, se cancela únicamente ese análisis y se muestra el motivo del fallo. El audio no se modifica y la reproducción no se detiene.</p><p>Para una recopilación larga, puedes aumentar el límite fijo, guardar y volver a pulsar Analizar pendientes. Cambiarlo no amplía ni reinicia un análisis que ya esté en ejecución.</p><p>Solo afecta al análisis de sonoridad. Los trabajos conservan los límites de recursos de la cola.</p></div></details></div><form method="post" class="sf-timeout-form"><input type="hidden" name="csrf_token" value="<?=lab_h(lab_auth_csrf_token())?>"><input type="hidden" name="embed" value="<?=$embed?'1':''?>"><input type="hidden" name="action" value="save_timeout"><label for="loudnessTimeoutMode">Modo<select id="loudnessTimeoutMode" name="loudness_timeout_mode"><option value="auto" <?=$timeoutMode==='auto'?'selected':''?>>Automático (3–30 minutos)</option><option value="fixed" <?=$timeoutMode==='fixed'?'selected':''?>>Fijo</option></select></label><label for="loudnessTimeoutMinutes">Minutos<input id="loudnessTimeoutMinutes" type="number" name="loudness_timeout_minutes" min="3" max="120" required value="<?=$timeoutMinutes?>" <?=$timeoutMode==='auto'?'disabled':''?>></label><button type="submit" class="btn primary">Guardar</button></form></section><section class="card sf-loudness-progress" id="loudnessProgress" aria-label="Progreso del análisis de sonoridad"><h2>Análisis de sonoridad</h2><div class="sf-loudness-progress-grid"><div class="sf-loudness-ring" role="progressbar" aria-label="Avance del lote" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><svg viewBox="0 0 128 128" aria-hidden="true"><circle class="track" cx="64" cy="64" r="54"/><circle class="fill" cx="64" cy="64" r="54"/></svg><strong data-progress-percent>0%</strong></div><div><p data-progress-summary role="status">Consultando progreso…</p><strong data-progress-track></strong><p class="muted" data-progress-stage></p><p class="muted" data-progress-counts></p><p class="muted">Este indicador corresponde únicamente al análisis de sonoridad. Puedes cerrar el panel; el trabajo continúa en el servidor.</p></div></div><section data-progress-failures class="sf-loudness-failures" role="alert" hidden></section><p data-progress-error role="status" hidden></p><button type="button" class="btn" data-progress-refresh>Actualizar progreso</button><script type="application/json" id="loudnessProgressInitial"><?=json_encode($progress,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_INVALID_UTF8_SUBSTITUTE)?></script></section><section class="card"><div class="stats"><div>Pistas con audio<strong><?=$audit['total']?></strong></div><div>Medición verificada para la fuente actual<strong><?=$audit['ready']?></strong></div><div>Pendientes o desactualizadas<strong><?=$audit['pending']?></strong></div><div>Último análisis fallido<strong><?=$audit['failed']?></strong></div></div><p class="muted">La comprobación identifica el audio analizado. Cambiar título o portada no requiere medir otra vez; reemplazar o recortar audio sí. Los análisis antiguos sin identificador de fuente se revisan una vez.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=lab_h(lab_auth_csrf_token())?>"><input type="hidden" name="embed" value="<?=$embed?'1':''?>"><button class="btn primary" type="submit" <?=$audit['pending']===0?'disabled':''?>>Analizar pendientes</button> <a class="btn" href="loudness_maintenance.php<?=$embed?'?embed=1':''?>">Actualizar</a></form><p class="muted">Trabajos de lectura con FFmpeg, un hilo por análisis y tiempo acotado. Respetan los límites y la protección de recursos de la cola general; las subidas tienen prioridad. No se reescribe ni comprime el audio. La preferencia Normalizar sigue siendo individual.</p></section></main></body></html>
